   665  // ------------------------------------------------------------------------------------------------
   666  void Parser::ParseLV3MapBlock(Texture &map) {
   667      AI_ASE_PARSER_INIT();
   668
   669      // ***********************************************************
   670      // *BITMAP should not be there if *MAP_CLASS is not BITMAP,
   671      // but we need to expect that case ... if the path is
   672      // empty the texture won't be used later.
   673      // ***********************************************************
   674      bool parsePath = true;
   675      std::string temp;
   676      while (true) {
   677          if ('*' == *filePtr) {
   678              ++filePtr;
   679              // type of map
   680              if (TokenMatch(filePtr, "MAP_CLASS", 9)) {
   681                  temp.clear();
   682                  if (!ParseString(temp, "*MAP_CLASS"))
   683                      SkipToNextToken();
   684                  if (temp != "Bitmap" && temp != "Normal Bump") {
   685                      ASSIMP_LOG_WARN("ASE: Skipping unknown map type: ", temp);
   686                      parsePath = false;
   687                  }
   688                  continue;
   689              }
   690              // path to the texture
   691              if (parsePath && TokenMatch(filePtr, "BITMAP", 6)) {
   692                  if (!ParseString(map.mMapName, "*BITMAP"))
   693                      SkipToNextToken();
   694
   695                  if (map.mMapName == "None") {
   696                      // Files with 'None' as map name are produced by
   697                      // an Maja to ASE exporter which name I forgot ..
   698                      ASSIMP_LOG_WARN("ASE: Skipping invalid map entry");
   699                      map.mMapName = std::string();
   700                  }
   220      // Dummies
   221      for (auto &dummy : mParser->m_vDummies)
   222          nodes.push_back(&dummy);
   223
   224      // build the final node graph
   225      BuildNodes(nodes);
   226
   227      // build output animations
   228      BuildAnimations(nodes);
   229
   230      // build output cameras
   231      BuildCameras();
   232
   233      // build output lights
   234      BuildLights();
   235
   236      // ------------------------------------------------------------------
   237      // If we have no meshes use the SkeletonMeshBuilder helper class
   238      // to build a mesh for the animation skeleton
   239      // FIXME: very strange results
   240      // ------------------------------------------------------------------
   241      if (!pScene->mNumMeshes) {
   242          pScene->mFlags |= AI_SCENE_FLAGS_INCOMPLETE;
   243          if (!noSkeletonMesh) {
   244              SkeletonMeshBuilder skeleton(pScene);
   245          }
   246      }
   247  }
