   249  void ASEImporter::GenerateDefaultMaterial() {
   250      ai_assert(nullptr != mParser);
   251
   252      bool bHas = false;
   253      for (std::vector<ASE::Mesh>::iterator i = mParser->m_vMeshes.begin(); i != mParser->m_vMeshes.end(); ++i) {
   254          if ((*i).bSkip) continue;
   255          if (ASE::Face::DEFAULT_MATINDEX == (*i).iMaterialIndex) {
   256              (*i).iMaterialIndex = (unsigned int)mParser->m_vMaterials.size();
   257              bHas = true;
   258          }
   259      }
   260      if (bHas || mParser->m_vMaterials.empty()) {
   261          // add a simple material without submaterials to the parser's list
   262          mParser->m_vMaterials.emplace_back(AI_DEFAULT_MATERIAL_NAME);
   263          ASE::Material &mat = mParser->m_vMaterials.back();
   264
   265          mat.mDiffuse = aiColor3D(0.6f, 0.6f, 0.6f);
   266          mat.mSpecular = aiColor3D(1.0f, 1.0f, 1.0f);
   267          mat.mAmbient = aiColor3D(0.05f, 0.05f, 0.05f);
   268          mat.mShading = Discreet3DS::Gouraud;
   269      }
   270  }
