   787  // Copy a texture from the ASE structs to the output material
   788  void CopyASETexture(aiMaterial &mat, ASE::Texture &texture, aiTextureType type) {
   789      // Setup the texture name
   790      aiString tex;
   791      tex.Set(texture.mMapName);
   792      mat.AddProperty(&tex, AI_MATKEY_TEXTURE(type, 0));
   793
   794      // Setup the texture blend factor
   795      if (is_not_qnan(texture.mTextureBlend))
   796          mat.AddProperty<ai_real>(&texture.mTextureBlend, 1, AI_MATKEY_TEXBLEND(type, 0));
   797
   798      // Setup texture UV transformations
   799      mat.AddProperty<ai_real>(&texture.mOffsetU, 5, AI_MATKEY_UVTRANSFORM(type, 0));
   800  }
