   802  // ------------------------------------------------------------------------------------------------
   803  // Convert from ASE material to output material
   804  void ASEImporter::ConvertMaterial(ASE::Material &mat) {
   805      // LARGE TODO: Much code her is copied from 3DS ... join them maybe?
   806
   807      // Allocate the output material
   808      mat.pcInstance = new aiMaterial();
   809
   810      // At first add the base ambient color of the
   811      // scene to the material
   812      mat.mAmbient.r += mParser->m_clrAmbient.r;
   813      mat.mAmbient.g += mParser->m_clrAmbient.g;
   814      mat.mAmbient.b += mParser->m_clrAmbient.b;
   815
   816      aiString name;
   817      name.Set(mat.mName);
   818      mat.pcInstance->AddProperty(&name, AI_MATKEY_NAME);
   819
   820      // material colors
   821      mat.pcInstance->AddProperty(&mat.mAmbient, 1, AI_MATKEY_COLOR_AMBIENT);
   822      mat.pcInstance->AddProperty(&mat.mDiffuse, 1, AI_MATKEY_COLOR_DIFFUSE);
   823      mat.pcInstance->AddProperty(&mat.mSpecular, 1, AI_MATKEY_COLOR_SPECULAR);
   824      mat.pcInstance->AddProperty(&mat.mEmissive, 1, AI_MATKEY_COLOR_EMISSIVE);
   825
   826      // shininess
   827      if (0.0f != mat.mSpecularExponent && 0.0f != mat.mShininessStrength) {
   828          mat.pcInstance->AddProperty(&mat.mSpecularExponent, 1, AI_MATKEY_SHININESS);
   829          mat.pcInstance->AddProperty(&mat.mShininessStrength, 1, AI_MATKEY_SHININESS_STRENGTH);
   830      }
   831      // If there is no shininess, we can disable phong lighting
   832      else if (D3DS::Discreet3DS::Metal == mat.mShading ||
   833               D3DS::Discreet3DS::Phong == mat.mShading ||
   834               D3DS::Discreet3DS::Blinn == mat.mShading) {
   835          mat.mShading = D3DS::Discreet3DS::Gouraud;
   836      }
   837
   838      // opacity
   839      mat.pcInstance->AddProperty<ai_real>(&mat.mTransparency, 1, AI_MATKEY_OPACITY);
   840
   841      // Two sided rendering?
   842      if (mat.mTwoSided) {
   843          int i = 1;
   844          mat.pcInstance->AddProperty<int>(&i, 1, AI_MATKEY_TWOSIDED);
   845      }
   846
   847      // shading mode
   848      aiShadingMode eShading = aiShadingMode_NoShading;
   849      switch (mat.mShading) {
   850      case D3DS::Discreet3DS::Flat:
   851          eShading = aiShadingMode_Flat;
   852          break;
   853      case D3DS::Discreet3DS::Phong:
   854          eShading = aiShadingMode_Phong;
   855          break;
   856      case D3DS::Discreet3DS::Blinn:
   857          eShading = aiShadingMode_Blinn;
   858          break;
   859
   860          // I don't know what "Wire" shading should be,
   861          // assume it is simple lambertian diffuse (L dot N) shading
   862      case D3DS::Discreet3DS::Wire: {
   863          // set the wireframe flag
   864          unsigned int iWire = 1;
   865          mat.pcInstance->AddProperty<int>((int *)&iWire, 1, AI_MATKEY_ENABLE_WIREFRAME);
   866      }
   867      // fallthrough
   868      case D3DS::Discreet3DS::Gouraud:
   869          eShading = aiShadingMode_Gouraud;
   870          break;
   871      case D3DS::Discreet3DS::Metal:
   872          eShading = aiShadingMode_CookTorrance;
   873          break;
   874      }
   875      mat.pcInstance->AddProperty<int>((int *)&eShading, 1, AI_MATKEY_SHADING_MODEL);
   876
   877      // DIFFUSE texture
   878      if (mat.sTexDiffuse.mMapName.length() > 0)
   879          CopyASETexture(*mat.pcInstance, mat.sTexDiffuse, aiTextureType_DIFFUSE);
   880
   881      // SPECULAR texture
   882      if (mat.sTexSpecular.mMapName.length() > 0)
   883          CopyASETexture(*mat.pcInstance, mat.sTexSpecular, aiTextureType_SPECULAR);
   884
   885      // AMBIENT texture
   886      if (mat.sTexAmbient.mMapName.length() > 0)
   887          CopyASETexture(*mat.pcInstance, mat.sTexAmbient, aiTextureType_AMBIENT);
   888
   889      // OPACITY texture
   890      if (mat.sTexOpacity.mMapName.length() > 0)
   891          CopyASETexture(*mat.pcInstance, mat.sTexOpacity, aiTextureType_OPACITY);
   892
   893      // EMISSIVE texture
   894      if (mat.sTexEmissive.mMapName.length() > 0)
   895          CopyASETexture(*mat.pcInstance, mat.sTexEmissive, aiTextureType_EMISSIVE);
   896
   897      // BUMP texture
   898      if (mat.sTexBump.mMapName.length() > 0)
   899          CopyASETexture(*mat.pcInstance, mat.sTexBump, aiTextureType_HEIGHT);
   900
   901      // SHININESS texture
   902      if (mat.sTexShininess.mMapName.length() > 0)
   903          CopyASETexture(*mat.pcInstance, mat.sTexShininess, aiTextureType_SHININESS);
   904
   905      // store the name of the material itself, too
   906      if (mat.mName.length() > 0) {
   907          aiString tex;
   908          tex.Set(mat.mName);
   909          mat.pcInstance->AddProperty(&tex, AI_MATKEY_NAME);
   910      }
   911      return;
   912  }
